function [summary,validation]=run_q6_procedure_subject001_estimation_contrast()
% Q6 Procedure subject001 estimation and extraneous-load contrast.
repo=fileparts(fileparts(fileparts(mfilename('fullpath'))));glm='C:\aliceproject\GLM';fl=fullfile(glm,'first_level');root=fullfile(repo,'results','q6_extraneous_procedure','cohort_specification','subject001');df=fullfile(fl,'nirs_spm_inputs_v2_fulltimeline_trial1','subject001','subject001_nirs_data.mat');addpath(fl);addpath(fullfile(glm,'toolboxes','spm'));addpath(genpath(fullfile(glm,'toolboxes','NIRS_SPM_v4_r1')));D=load(df,'nirs_data');nch=D.nirs_data.nch;M=readtable(fullfile(fl,'nirs_spm_inputs','subject001','subject001_channel_metadata.csv'),'TextType','string');summary=table();validation=table();
for hb=["HbO","HbR"]
 sf=fullfile(root,char(hb),sprintf('SPM_indiv_%s.mat',hb));L=load(sf,'SPM_nirs');S=L.SPM_nirs;if ~isfield(S.nirs,'step')||~strcmpi(string(S.nirs.step),'estimation'),nirs_spm_estimation_batch_fixed(sf,df);L=load(sf,'SPM_nirs');S=L.SPM_nirs;end;B=double(S.nirs.beta);assert(isequal(size(B),[5 nch]));N=string(S.xX.name(:));targets=["LILEProcedure","HILEProcedure","LIHEProcedure","HIHEProcedure"];k=zeros(4,1);for i=1:4,k(i)=find(contains(N,targets(i)),1);end;c=zeros(5,1);c(k)=[-.5 -.5 .5 .5];rss=double(S.nirs.ResSS);if ~isvector(rss),rss=diag(rss)';end;dfree=double(S.xX.erdf);b=c'*B;se=sqrt(max((c'*double(S.xX.Bcov)*c).*(rss/dfree),0));t=b./se;p=betainc(dfree./(dfree+t.^2),dfree/2,.5);q=bh(p);R=table(repmat("subject001",nch,1),repmat(hb,nch,1),(1:nch)',string(M.channel_id),string(M.channel_type),string(M.roi),string(M.laterality),b(:),se(:),t(:),p(:),q(:),repmat(join(string(c'),' '),nch,1),'VariableNames',{'subject_id','hemoglobin','channel_index','channel_id','channel_type','roi','laterality','contrast_beta','contrast_se','contrast_t','contrast_p_two_sided','contrast_q_bh61','contrast_vector'});writetable(R,fullfile(root,sprintf('subject001_%s_q6_high_extraneous_minus_low_extraneous_procedure_channel_contrasts.csv',hb)));summary=[summary;table(hb,nch,sum(p<.05),sum(q<.05),mean(b),median(b),'VariableNames',{'hemoglobin','n_channels','n_p_lt_005','n_q_bh61_lt_005','mean_contrast_beta','median_contrast_beta'})];validation=[validation;table(hb,size(B,1),size(B,2),dfree,all(isfinite(B),'all'),all(isfinite(b)),'VariableNames',{'hemoglobin','n_beta_rows','n_channels','effective_df','beta_all_finite','contrast_all_finite'})];
end
writetable(summary,fullfile(root,'subject001_q6_procedure_contrast_summary.csv'));writetable(validation,fullfile(root,'subject001_q6_procedure_contrast_validation.csv'));disp(summary);disp(validation);
end
function q=bh(p),q=nan(size(p));v=isfinite(p);pv=p(v);[s,o]=sort(pv(:));m=numel(s);z=min(1,flipud(cummin(flipud(s.*m./(1:m)'))));zv=zeros(size(pv));zv(o)=z;q(v)=zv;end
